// package.json — ADD THIS DEPENDENCY. It is not part of better-auth.
//   "@better-auth/mcp": "1.7.5"

import { betterAuth } from "better-auth";
import { jwt } from "better-auth/plugins";          // REQUIRED: without it mcp() throws BetterAuthError: jwt_config
import { mcp, requireMcpAuth } from "@better-auth/mcp";

export const auth = betterAuth({
  baseURL: "https://hub.example.com",               // AS issuer becomes <baseURL>/api/auth
  database: /* ... */,
  plugins: [
    jwt(),
    mcp({
      loginPage: "/login",                          // REQUIRED (no default)
      consentPage: "/consent",                      // REQUIRED (no default)
      resource: "https://hub.example.com/mcp",      // REQUIRED. https (or loopback http). No query, no fragment.
      // allowDynamicClientRegistration: true,      // RFC 7591 — default FALSE
      // allowUnauthenticatedClientRegistration: true,
      // resources: ["https://hub.example.com/mcp/github", ...],  // extra audiences for a multi-server hub
      // enforcePerClientResources: true,
      // scopes: ["openid", "profile", "email", "offline_access", "mcp:read", "mcp:call"],
    }),
  ],
});

// Guard the MCP transport route. Claims (incl. `aud`) are handed to the handler
// ONLY after issuer/audience/signature/expiry are verified against the AS JWKS.
export const POST = requireMcpAuth(
  auth,
  async (req, claims) => {
    claims.aud;        // => "https://hub.example.com/mcp"  <- the audience the spec wanted
    claims.scope;      // => "mcp:read mcp:call"
    claims.sub;        // user id, or client id for client_credentials
    claims.client_id;  // always present
    return handleMcp(req, claims);
  },
  {
    resource: "https://hub.example.com/mcp",  // defaults to $context.baseURL — SET IT EXPLICITLY
    requiredScopes: ["mcp:call"],             // 403 + RFC 6750 insufficient_scope listing what's missing
  },
);

// Resource server deployed separately from the AS, or dynamic baseURL:
import { createMcpProtectedRequestHandler } from "@better-auth/mcp";
const handler = createMcpProtectedRequestHandler(
  { issuer: "https://hub.example.com/api/auth",
    audience: "https://hub.example.com/mcp",
    jwksUrl: "https://hub.example.com/api/auth/jwks",
    requiredScopes: ["mcp:call"] },
  async (req, claims) => new Response("ok"),
);

// REAL paths (basePath is /api/auth):
//   /api/auth/oauth2/authorize            /api/auth/oauth2/token
//   /api/auth/oauth2/userinfo             /api/auth/oauth2/introspect
//   /api/auth/oauth2/revoke               /api/auth/oauth2/register
//   /api/auth/oauth2/consent              /api/auth/oauth2/continue
//   /api/auth/oauth2/end-session          /api/auth/jwks
//   /api/auth/.well-known/oauth-authorization-server   (also /.well-known/oauth-authorization-server/api/auth)
//   /api/auth/.well-known/openid-configuration
//   /.well-known/oauth-protected-resource               (ROOT, not under basePath)
//   /.well-known/oauth-protected-resource<resource path>
//   /admin/oauth2/resources[/:identifier[/clients/:client_id]]
// NOTHING mounts under /api/auth/mcp/.
